<script setup lang="ts">import{onMounted,ref}from'vue';import AppHeader from'../../components/AppHeader.vue';import{api}from'../../api/client';import type{OrderSummary}from'../../domain/types';const orders=ref<OrderSummary[]>([]),loading=ref(true),error=ref('');onMounted(async()=>{try{orders.value=await api.getOrders()}catch{error.value='订单摘要读取失败'}finally{loading.value=false}});const open=(ref:string)=>uni.navigateTo({url:`/pages/order/detail?orderRef=${encodeURIComponent(ref)}`})</script>
<template><view class="page"><AppHeader left="首页" right="恢复" @left="uni.reLaunch({url:'/pages/index/index'})" @right="uni.navigateTo({url:'/pages/order/recovery'})"/><view class="content"><text class="kicker">订单 / UX-P020</text><view class="heading" role="heading" aria-level="1">我的订单</view><text class="desc">只展示当前已授权的订单摘要；空列表不证明其他主体没有订单。</text><view class="tag-row"><text class="tag success">全部</text><text class="tag">处理中</text><text class="tag">需关注</text></view><view v-if="loading" class="card" role="status">加载中…</view><view v-if="error" class="card risk" role="alert">{{error}}</view><button v-for="item in orders" :key="item.orderRef" class="card order" :aria-label="`查看订单 ${item.maskedPhone}`" @click="open(item.orderRef)"><view><text class="card-title">{{item.maskedPhone}}</text><text class="copy">合成商品摘要 · 投影 v{{item.projectionVersion}}</text></view><view><text class="tag" :class="item.stateCode==='REVIEW'?'risk':'unknown'">{{item.stateCode}}</text><text class="amount">CNY {{(item.total.minor/100).toFixed(2)}}</text></view></button><view v-if="!loading&&!error&&!orders.length" class="card empty">当前没有可展示的授权摘要，可返回首页或发起通用恢复。</view></view></view></template><style src="../../styles/shared.css"></style><style scoped>.order{width:100%;display:grid;grid-template-columns:1fr auto;gap:16rpx;text-align:left;line-height:1.4}.amount{display:block;margin-top:16rpx;font-weight:800}.risk{color:var(--risk)}.empty{text-align:center;color:var(--muted);padding:80rpx 30rpx}</style>
